import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷五","description":"周易經傳集解 - 周易經傳集解卷五","frontmatter":{"title":"周易經傳集解卷五","description":"周易經傳集解 - 周易經傳集解卷五"},"headers":[],"relativePath":"classics/jingchuan-jijie/006.md","filePath":"classics/jingchuan-jijie/006.md"}'),r={name:"classics/jingchuan-jijie/006.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷五",tabindex:"-1"},[n("周易經傳集解卷五 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷五","aria-label":"Permalink to “周易經傳集解卷五”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解小畜履卷五 ​宋林栗撰。序卦曰：「比者，比也。比必有所畜，故受之以小畜。」「畜」之為義，說者曰：「止者，聚也、養也。」夫止者，「艮」之義也；聚者，「萃」之義也；養者，「頤」之義也。以之訓「畜」，皆不固矣。至於聖人，亦豈云爾哉？曰：「比必有所畜」而已。稽其近似，蓋有含畜之意焉。何則？實不能以畜實，虛則能之；剛不能以受剛，柔則能之。然則止也、聚也、養也，亦兼明之矣。自「比」之「畜」，「坤」變為「乾」，「坎」變為「巽」，而成卦也。天下之所以「比」於九五者，以天下皆柔，惟五之為剛也；天下皆弱，惟五之為強也。夫天下之人，豈盡柔弱而已乎？材智勇健，固不乏人矣。為九五者，豈必智勇出於其上而後為之君哉？其必有以畜之矣。梁襄王問於孟子曰：「天下烏乎定？」對曰：「定於一。」「孰能一之？」曰：「不嗜殺人者能一之。」「孰能與之？」曰：「天下莫不與也。」其比畜之義乎？是故自比之畜，變其四爻，其不動者，九五、六四矣。然則五之所以畜之者，非六四而誰歟？是故畜有大小，「大畜」，君也；「小畜」，臣也。以一陰而畜五陽，其小之何也？以其近君之位，而體柔巽之行，是以謂之「小畜」也。小畜：亨。密雲不雨，自我西郊。彖曰：小畜，柔得位而上下應之，曰「小畜」。健而異，剛中而志行，乃亨。「密雲不雨」，尚往也。「自我西郊」，施未行也。下乾上巽成卦曰「小畜」者，「乾」為健，「兌」為說，「離」為麗，「巽」為入。天下之健者，說而麗之，非有以「巽」而入焉，其能畜之乎？故曰：「小畜，亨。」以「巽」畜「乾」，以一柔畜五剛，小畜大之義也。畜大而能「亨」者，「柔得位而上下應之」也。六四也者，近君之位也。以六居之，得其位矣。上承九五，得其君也；下接三陽，得其助也。得其位，得其君，得其助，則天下聰明才智勇敢之士，莫不說而麗之，此其所以能「亨」也。故曰：「柔得位而上下應之，曰小畜。」夫六四者，畜之宗也。九五者，畜之主也。四之畜之也，豈自為哉？凡以九五之故也。五雖中正，以健制健，必不畜矣；以剛御剛，必不容矣。今健而下「巽」，剛中而志行，是以畜而亨也。故曰：「健而巽，剛中而志行，乃亨。」「密雲不雨，自我西郊」，何謂也？曰：雲雨，「坎」也。「小畜」反覆八象，未嘗有「坎」，而彖言「密雲不雨」，四言「有孚，血去惕出」，上言「月幾望」，皆「坎」象也。學者可不求其故哉？或曰：「敢問其故？」曰：「小畜」之「坎」，由比來也。觀夫序卦，則得之矣。比之六四、上六，「坎」也。其九五，坎之中爻也。自比之畜，不變者二爻耳。是以上卦之「巽」有坎象焉，明其所從來也。或曰：「凡卦之象，莫非有所從來也。既以為小畜矣，而猶有比象，其在他卦，何獨不然？」曰：他卦亦固有之，不若小畜之象，全取乎比也。所以然者，何哉？為其畜之故也。比而後畜，則巽之有坎，不亦宜乎？或曰：然則安在其為密雲而不雨也？曰：為其畜之故也。坎變為巽，而在乾之上，雲雨之氣既升乎天，以一陰而受五陽之歸，是以盤旋蓊鬱，畜為雲密，而膏澤不下流也。其曰自我西郊，何也？曰：「我」，六四也。六四視二為「兌」，視上亦為「兌」。「兌」，西方也。「坤」之彖曰：「西南得朋，乃與類行。東北喪朋，乃終有慶。」是故天氣下降，地氣上騰，陽居其所，陰喪其朋，然後雲行而雨施。今六四之「巽」，既上騰矣，然而未離其類，自我西郊，是以屯其膏而未下也。子曰：「密雲不雨」，尚往也。「自我西郊」，施未行也。尚往之為言，猶言乃與類行雲爾。自我西郊，而未達於東北，施之未行，不亦宜乎？東北，「艮」也，自東北而震也。夫「畜」以「艮」畜「乾」，而九三、上九皆有「震」體，此其所以異於「小畜」歟？象曰：風行天上，「小畜」，君子以懿文德。「天」者，「乾」也。「風」者，「巽」也。「風行天上」，則為發號施令之象；行於地上，則為觀民設教之象。今也行於天上，其猶號令之未發，政教之未施乎？固已畜之於此矣。惟天為大，而風行其上，小之畜大，亦如是也。故君子象之，「以懿文德」。「懿」之言美也。美其文德，以發號施令，觀民設教，無適而不宜矣。雜卦曰：「小畜，寡也。」「畜」之為卦，以柔畜剛，以「巽」畜「乾」也。夫「乾」，天下之至健也，而「巽」之長女以柔畜之，「乾」之受制，不亦難乎？然卦惟一柔，而諸爻皆剛，以剛遇剛，不能相下，其勢必歸於柔。以五剛而歸一柔，柔至寡而剛至眾，欲無受畜，不可得矣。是故陽見乘陵則為「反目」，陰能乘順則為「攣如」，遠而相得則為「複道」，同體而相說則為「牽復」，為「載德」，皆即六四以言其義也。然則以一柔而畜五剛，非至寡，其孰能之？初九：復自道，何其咎？象曰：「復自道」，其義吉也。初九，「乾」也。以陽居剛，而在一卦之下，應乎六四之「巽」，故曰「復自道」。「乾」之九三，「終日乾乾」，其象曰：「反覆道也。」今初九之「乾」，方受六四之畜，未可以進，復自道而已，故曰：「何其咎，吉。」初在一卦之下，體乎「乾」剛，復自其道，又何咎之有哉？既免於咎，斯為吉矣。方畜之時，一陰在上，牽制群動，初九之君子雖在下位，與之為應，但能反覆其道，無所迎將，吉孰如之？故子曰：「復自道，其義吉也。」九二：牽復，吉。象曰：「牽復」在中，亦不自失也。九二，「兌」也。以陽居柔而在下卦之中，上無其應，而連於六四之「巽」，故曰「牽復」。「牽」，連也。二四同體，故有「牽復」之象。君子在下，不得於君而得於大臣，雖為所牽，而能居中守正，反覆其道，不為屈撓，牽而能復者也，故曰「吉」。子曰：「牽覆在中，亦不自失也。」以其居中，知其能自免矣。九三，輿說輻，夫妻反目。象曰：「夫妻反目」，不能正室也。九三下體為「乾」，上體為「離」，以陽居剛而在下卦之上，上無其應，承於六四之「巽」，故曰「輿說輻」。「巽」、「離」、「兌」皆出乎「坤」，「坤」為大輿，「離」為麗，「巽」為入，為伏，故有「輿說輻」之象。「說輻」則輿不行矣。其所以說輻而不行者，則受畜故也。夫「輿」之言眾也，其象車也。象載車而行，是必人之豪傑、師之尊長也。說輻而受制，是必有其道矣。九二之輿，已有毀拆之象，而未遇其配，志猶上行。至於九三而遇六四，「離」「坎」相合，則說其輿輻矣。三說其輻，則二之牽復不亦宜乎？然三同志上行，受畜於四，豈其所願哉？故曰「夫妻反目」。「離」為目，「坎」為青，「巽」為多白眼，故有「夫妻反目」之象。「反目」，怒而相睨，則乖閡之睛也。六為畜之宗，處九於五而自下畜之，則上下相安而有攣如之孚，善畜君者也。若處九於三而自上畜之，則是婦制其夫，臣制其君也。三以「乾」之剛，以「離」之明而受畜於四，又見其陵，則其不和而反目宜矣。是以聖人體天地，法陰陽，製為夫婦室家之禮，剛上而柔下，男行而女隨，然後可以長久而無乖閡之患。故子曰：「夫妻反目，不能正室也。」謂九三在下而六四在上故也。六四：有孚，血去惕出，無咎。象曰：「有孚」「惕出」，上合志也。六四上體為「巽」，下體亦為「巽」，以陰居柔而在上卦之下，應乎初九而介於九三、九五之間。初與三為「乾」，三與五為「離」，故曰「有孚，血去惕出，無咎」。四之為「巽」，由坎變也。「坎」為有孚，為「血」，為「惕」。「有孚」謂承五也，「血」「惕」，謂乘三也。「血」之言「惕」，「惕」之言懼也。六四在「比」，既以「孚」為九五矣，至畜而成剛，故有相懼之象焉。謂其既比為五，而能「巽」以畜之，志同義合，誠信已孚，則禍患之來，不旋踵而自去，憂懼之至，不轉瞬而自消。所以然者，「坎」變為「巽」故也，故曰「無咎」。子曰：「有孚惕出，上合志也。」居近君之位，持宰物之權，上下五陽，唯己之聽，欲無傷懼，不亦難乎？唯其盡忠竭誠，與上合志，使讒間之口不能得其隙而議之，然後可以免矣。九五，有孚攣如，富以其鄰。象曰：「有孚攣如」，不獨富也。九五，「離」也。以陽居剛，而在上卦之中，下無其應，而乘六四之「巽」，故曰「有孚攣如」。「攣」，猶納也。易以遠而配為「交如」，近而合為「攣如」，言綢繆固結也。六四之「巽」，猶有「坎」象，其過九五，「離」「坎」相合，可謂「攣如」之孚矣，故曰「富以其鄰」。陽為富，陰為貧。「以」，猶用也，鄰猶臣也。書曰：「欽四鄰。」又曰：「臣哉鄰哉！鄰哉臣哉。」以其密邇於五，故以鄰言之矣。六四者，畜之宗也，本乎陰虛，故能受眾陽之歸。然豈將據而有之哉？蓋以九五在上，有智勇過人之資，苟與天下爭能而角技，則天下之智勇未必皆「比」，其下將不必服而臣之矣。是故用其柔「巽」以畜納之，使下之智勇不以犯其上，上之智勇不以勝其下，上安於為君，而下安於為臣。故六四之畜，凡以為九五之用也。書曰：「如有一個臣，其心休休焉，其如有容。人之有技，若己有之；人之彥聖，其心好之，不啻如自其口出，是能容之，以保我子孫黎民。」其六四之謂歟？然九五方受畜於四，而乃能用之，何哉？以其富也。貴為天子，富有天下，而樂與賢者共之，是以能用之也。子曰：「有孚攣如，不獨富也。」富也者，人主之所獨也。「樂與賢者共之」，則賢者樂為之用，安富尊榮，有隆無替，豈與愚夫愚婦獨富而無鄰者同日語哉？上九：既雨既處，尚德載，婦貞厲，月幾望，君子徵兇。象曰：「既雨既處」，德積載也；「君子徵兇」，有所疑也。上九，「兌」也。以陽居柔，而在一卦之上，下無其應，而連於四之陰，乘乎五之陽，故曰「既雨既處」。夫「巽」「離」「坤」「兌」者，陰之所也；「乾」「坎」「艮」「震」者，陽之方也。陰離其類也，而之乎陽，陰陽和而後雨。今「小畜」之陰，由「巽」而之「兌」，是以「畜」為「密雲」而已。然「小畜」以柔畜剛，下之三陽，臣也；以臣畜君，上之九五是也。上九一爻，乘九五之剛，而受六四之畜，將何義以處之？其臣之元勳舊德，人主所尊尚者歟？說以從巽，斯受其畜矣，故以「既雨」之義明之。四之為「巽」，由坎變也。自坎而之「巽」，自「巽」而之「兌」，其「既雨」而復其所乎？既雨而復，則功臣之象也，故曰「尚德載」，畜德之盛而天下載之，是以九五尚之也。夫以人臣而居成功之地，有積德之名，世主之所忌也。不能奉身以退，而猶貞固守之，危之道也。故曰：「婦貞厲，月幾望，君子徵兇。」離為日，「坎」為月。月之望與日為衡，分天之中，故謂之「望」。望則疑為日矣。日中則昃，月盈則虧，天之道也。月之幾望，其極盛之時乎？君子不戒而徵，則兇矣。君子者，對婦而言也。在家為夫婦，在國為君臣，聖人之所以為戒深矣。故子曰：「既雨既處，德積載也。君子徵兇，有所疑也。」德盛而名尊，位高而權重，有疑陽之勢矣。序卦曰：「物畜然後有禮，故受之以履。」「履」之成卦，畜之反也。「履」之三，即「畜」之四也。「履」之兌，即「畜」之「巽」也。夫以一陽而為五陽之主，雖非天位，而五陽居之，在四而能畜者，當位而承乎五也。今居三不當其位，不承九五，以為君則不正，以為臣則不順，故不足以主一卦之義，而取其上下二體，名之曰「履」焉。「乾」者，陽之至尊；「兌」者，陰之至卑。莫高乎天，莫下乎澤。上安其尊，下守其卑。君子履之，臣民藉焉，斯之謂「履」矣。夫天下才智勇敢之士，莫不有上人之心。及其未受畜也，跳踉咆哮，無所不至；及其既畜矣，入吾含畜之內，然後上下之分定，而禮行乎其間矣。是故「乾」以健而行，「兌」以說而應。雖其下有二陽，而安為之藉，莫有爭心，斯以履、以畜之義也。履虎尾，不咥人，亨。彖曰：「履」，柔履剛也。說而應乎乾，是以「履虎尾，不咥人，亨」。剛中正，履帝位而不疚，光明也。下兌上乾成卦曰「履」者，初為「兌」，二為「離」，三為「巽」，四為「乾」，五為「兌」。巽、離、兌為三女，言「乾」則包三子，言「三女」則包「坤」。三陽在上，三陰在下，尊卑之分不既明矣乎？是以謂之「履」也。故曰：「履，柔履剛也。」柔履乎剛，「履」之象著矣。夫「履」之為言，自上履下也。不曰「剛履柔」，而曰「柔履剛」者，猶孟子「小役大，弱役強」之義。剛之履柔，以勢言之也。柔履於剛，心說而誠服矣。謂之有禮，不亦宜乎？「履虎尾，不咥人，亨」，何謂也？曰：乾為人，「兌」為虎。虎，陰物也；「兌」，西方之卦，有虎之象焉；又為口，有咥之象焉。「乾」在其上，有「履虎尾」之象焉。履虎之尾，其首必反，未有不見咥者也。而又言「不咥人，亨」，何也？為其既已畜之矣，馴習於人，履之而不咥，宜哉！傳曰：「虎之與人異類而婿養。」異者，順也。婿猶說也，順猶「巽」也。此「巽」之所以為「畜」，而「兌」之所以為「履」也。故曰：「說而應乎乾，是以履虎尾，不咥人，亨。」彼說而應乎我，故履之而不吾咥也。履之而不吾咥，足以為無咎而已，何自亨哉？夫子於是發明之曰：「剛中正，履帝位而不疚，光明也。」所以釋「亨」之義也。「乾」之三陽，有相終始之義。「剛中正」謂五也，以九居五故也。「履帝位」，謂上也，履乎天位故也。「不疚光明」，謂四也，體乎離明故也。「履虎尾而不咥」，則「剛中正，履帝位而光明不疚」，不亦亨乎！象曰：上天下澤，「履」，君子以辨上下，定民志。「天」者，「乾」也；「澤」者，「兌」也。莫高乎天，莫下乎澤，君子體之，「以辨上下」，而民志定矣。雜卦曰：「履，不處也。」「履」之為卦，上休履下也。其在六位，上爻履下爻也。以剛履剛，得所履則吉；以柔履剛，以剛履柔，失其所履，則有虎尾之厲焉。「履虎尾」，宜見咥者也。履之而不見咥者，履而不處，九四是也。若履而處之，咥人宜矣。陽為行，陰為處。五陽之爻皆「吉無咎」，而六三獨兇者，謂其履而處之也。初九：素履，往，無咎。象曰：「素履」之往，獨行願也。初九，「兌」也。以陽居剛，而在一卦之下，上無其應，下無所履，而承於九二之「離」，故曰「素履」。「兌」，西方之卦，而色白，有「素履」之象焉。「履」以所履之爻為義，既無所履，則取其所往，以陽居剛，履得其正，而謂之「素履」焉。賢人君子，身處卑賤，見履於人，遺逸而不怨，厄窮而不閔。履其素而已履者，禮也。燔兔匏葉，可以行禮；啜菽飲水，可以事親。君子所履，於是素矣。素履而行，何咎之有？子曰：「素履之往，獨行願也。」君子得其時，得其位，推其所履以兼善天下，豈非素願也哉？不得其位，不得其時，獨行諸身而已，豈往而求之哉？九二：履道坦坦，幽人貞吉。象曰：「幽人貞吉」，中不亂也。九二，「離」也。以陽居剛，而在下卦之中，上有九五而非其應，乘初九之剛，而履於六三之柔，故曰：「履道坦坦，幽人貞吉。」「離」也者，明也。日中而行，得其所履坦坦之道也。既以體乎離明，而履坦坦之道，宜若可以行矣，而乃曰「幽人貞吉」，何也？為其以九居二，遠不應五，而近臣六三，三之眇跛，不足與有為也。往而從之，陷於亂人矣。惟幽潛之君子，為能貞固守之，斯為吉也。或曰：離為明，坎為幽，二體「離」而謂之幽人，則「離」、「坎」之象可以互用乎哉？曰：以幽而眩明，其明乃所以為幽也；以明而守幽，其幽祗所以為明歟？以九居二，故有幽人之象也。或曰：初無所履而猶往無咎，二得其所履而不保其往，何也？曰：初處最下，遠無所應，近無所承，其往也，獨行其素而已，必「無咎」也。若夫九二履於六三，陰陽相求，物之情也。二之往也，非三而誰從？故必貞而後「吉」也。子曰：「幽人貞吉」，中不自亂也。卦惟一陰，而九二承之，烏知其「貞吉」而不為「貞兇」也哉？其以剛中，知其不自亂矣，是其所以為「貞吉」者也。若利害得喪亂於其中，尚能守其中貞也哉？六三：眇能視，跛能履，履虎尾，咥人，兇。武人為於大君。象曰：「眇能視」，不足以有明也。「跛能履」，不足以與行也。「咥人」之兇，位不當也。「武人為於大君」，志剛也。六三上體為「巽」，下體為「巽」，以陰居剛，而在下卦之上，視二為「離」，視四亦為「離」。視初為「兌」，視五亦為「兌」。故曰：「眇能視，跛能履。」「離為目」，「巽為多白眼」，眇而能視也。「巽為股」，「兌為毀折」，跛而能履也。為其陰柔不中不正，故以眇跛言之也。故曰：「履虎尾，咥人兇。」「兌為虎」，三履其中，以柔履剛，失其所履，「履虎尾」也。「兌為口」，「巽」為入，入於虎口，咥人之象也。虎之踞也，其尾旋焉，是以既為尾，而又為口也。巽為伏，為進退，為不果。陰柔之性，貪利忘反，見難而不能去，履而處之之象也。夫眇而不能視，跛而不能履，則安分而止矣，豈有虎尾之憂哉？為其眇而自以為能視，跛而自以為能履，故冒險而行，履虎尾而不知危也。履乎虎尾，明不足以見，強不足以行，履之而不去，安有不見咥者？或曰：「武人為於大君」，以六居三，不當其位，小人而乘君子之器，「武人為於大君」之象也。以獨陰居下卦之上，在五陽之中，視天下莫己若，遂有為大君之志，不知其所履者，天下之至危也。武而無謀，履非其據，足以殺其身而已矣。夫六三者，小畜之六四也。自畜而履，保其常心，則彖所謂「說而應乎乾」者也。說而應乎乾，則上下辨而民志定矣。而三以重巽之體，居離兌之中，不能自克，以及於難，故九五於三「旋其吉」，而上九於三「考不祥」。吉凶無常，唯所召耳。子曰：眇能視，不足以有明也；跛能履，不足以與行也。咥人之兇，位不當也。「武人為於大君，志剛也。」三在二四之中，而有應在上，此其所以有為君之質，雖柔而求至剛矣，是以謂之「武人」也。若以六居五，履信而思順，當位而尚賢，以一陰為眾陽之歸，豈有武人之象哉？九四：履虎尾，訴訴，終吉。象曰：「訴訴終吉」，志行也。九四上體為「乾」，下體為「離」，以陽居柔而在上卦之下，履六三之柔，而履於五之剛，故曰：「履虎尾，訴訴，終吉。」三，「兌」也，終「兌」為虎，四履其上，以剛履柔，失其所履，「履虎尾」也。「訴」與「溯」同，「溯」猶行也。溯溯，行而不止也。三之陽而上行，故有「溯溯」之象。「乾」為剛，「離」為明，明足以見，剛足以行，是以知危而不履也。在「兌」之上，已進乎「乾」，履而不處，說乎虎口矣。說乎虎口，未可以言吉，吉在其終也。子曰：「訴訴終吉，志行也。」志在於行，說乎虎口，至於上九，而後「元吉」以終之。此彖所謂「不咥人亨」者歟？九五：夬履，貞厲。象曰：「夬履貞厲」，位正當也。九五，「兌」也。以陽居剛，而在上卦之中，承柔皆剛，得其所厲矣，故曰：「夬履，貞厲。」「夬」之言決也。在易之「夬」，剛決柔，「乾」決兌也。九五在上，而六三「武人慾為大君」，當是之時，可以決而去之矣。「夬」之九五所以不利即戒者，以至剛而決至柔，以至盛而決至衰。物極則反，人窮則詐，有危道焉。故曰：「中行無咎，中未光也，」謂其健而不說，決而不和也。至「履」之九五，本剛健之資，而體乎柔說之道，故曰：「剛中正，履帝位而不疚。」光明也，謂其健而說，決而和也。是故「履」皆以「乾」決「兌」，而「履」之五有「兌」象焉。以「乾」決「兌」，猶懼其危；以「兌」決「兌」，蔑不濟矣。然則系之「貞厲」，何也？凡易言「貞」與「徵」，為相反之辭。「徵」猶行也，貞猶固也。以徵為兇者，以貞為吉；以貞為厲者，以徵為亨也。養虎為患，前志所戒，五之「貞厲」，不亦宜乎？子曰：「夬履貞厲，位正當也。」以五之正當，決三之不當，可以決之而無疑矣。然猶貞固守之，長奸縱惡，危之道也。上九：視履考祥，其旋元吉。象曰：「元吉」在上，大有慶也。上九，「乾」也。以陽居柔，而在一卦之上，「履」乎九五而不為人之所履，故曰：「視履考祥，其旋元吉。」上履之終也，以柔濟剛，履道之成也。「履」乎九五，履天位也。以剛履剛，得其所履，可以安行矣。然猶視而後履，謹之至也。書曰：「若跣弗視地，厥足用傷。」視「履」之謂也。視言柔，「履」言剛也。九四、上九皆得之矣。九四視而後履者，雖未免虎尾之危，其覺而去速矣。六三之視「履」，所謂眇者不足以與明，跛者不足以與行也。至於九四，體「離」之明，體「乾」之健，以「離」而視，則無不察矣；以「乾」而「履」，則無不亨矣。然而非其所履，未可以言吉也。至於上九，卦之終也。兢兢業業，謹終如始，上九之謂也。視履之祥，至於此而後見也。考之為言，成而可校也。祥之為言，善而得福也。旋之為言，反而有歸也。福善禍淫，天之道也。然為善者，有時而逢殃，為惡者，有時而獲福。是以世之人疑焉，蓋不考之於其旋故也。考其旋，則善惡之報無不驗矣。君子之為善也，非以僥倖於目前之福也。擇而履之，一舉足不敢易也。凜然如履虎尾而將咥人，是以見利而思害，臨福而憂禍。思則利有所不就，憂則福有時而辭之，較之目前，有不及宜行者矣。及其旋而考之，元吉之所歸也。此文王、孔子之所以行乎憂患，而不改其操也歟？故曰：「履，德之基也。」視而後履，所以為德之基也。又曰：「履和而至」，以兌濟乾，以柔濟剛，所以為和而至也。又曰：「履以和行，始乎訴，訴中吉，終乎視履，所以和其行。至於上九，其裕後矣。積善之家，必有餘慶，不在其身，必在其子孫也。謂之元吉，不亦宜乎？」子曰：元吉在上，大有慶也。上九體乾，乾為大，應在六三，陰陽相得，謂之大有慶。夫以五之中正，宜元吉矣。今元吉猶在上者，謂其大而且有慶也。不計目前之福，而考之於其旋，子孫之慶，寧有窮乎？此之謂大有慶也。非文王之孫子，其誰足以當之哉？履卦序說。子曰：「易有太極，是生兩儀，兩儀生四象，四象生八卦，八卦定吉凶，吉凶生大業。有物混成，是謂太極。天尊地卑，是謂兩儀。坎、離、震、兌，是謂四象。乾、坤、艮、巽，是謂八卦。」然子言「易有太極」，以至「吉凶大業於是乎生」。前此數者，既已興於爻象之中矣。愚讀易至履卦，始得四象、八卦之說，知聖人之所以示我者，獨詳言之。今夫總六畫而成卦，謂之履者，太極之象也。系之曰：「兌下乾上者，兩儀之象也。」初至三為「兌」，二至四為「離」，三至五為「巽」，四至上為「乾」，此則「兩儀生四象」也。初為「兌」，五亦為「兌」；二為「離」，四亦為「離」；四為「乾」，上亦為「乾」。惟六三一卦，上體為巽，下體亦為巽。此則四象生八卦也。八卦成，而吉凶可定，吉凶定，而後大業於是乎生矣。是故四象者，卦之所以立也；八卦者，爻之所以分也。不知四象，無以盡一卦之性；不知八卦，無以辨六爻之情。八卦之在四象，猶八極之在四方也。言四象，則八卦在其中矣。故曰：「易有四象，所以示也；繫辭焉，所以告也；定之以吉凶，所以斷也。」夫四象者，於數為七八九六，於時為春夏秋冬，於象為金木水火，於德為仁義禮智。然而是數者，易之所以非其所有也。易之所藏，非其所示也。若夫有而示之，則於前之所陳非邪？凡易之中有是四象，所以示人者也。雖以示之，未之能察也，聖人又系之辭焉，如「履虎尾」、「素履」之類，所以告之也。雖以告人，未之能決也，聖人又定之以吉凶，如「不咥人，亨，往無咎」之類，所以斷之也。聖人之為後世君子，可謂憂之深而愛之篤矣。子曰：「文王既沒，文不在茲乎？天之將喪斯文也，後死者不得與於斯文也。」雖然，「苟非其人，道不虛行。」顏氏之子不幸早世，仲尼之所為慟哭也。蓋家語所載者，商瞿子木受易於夫子，雖其學於今無傳，然漢之言易者，皆本其所自出也。愚嘗疑之。子木之賢，與其答問於孔子之書，夫豈人不足列於高弟，而乃以微言奧旨傳之歟？世人有子夏易說者，其繆妄可讀而知矣。舊傳韓嬰、丁寬所著，已不可考，恐今本又非昔書。近人晁說之以道自著其說，名曰商瞿易傳，子夏之書，亦其類歟？按春秋左氏，卜筮之家，頗用四象，至漢以來，言易者謂之五體。而鄭玄、虞翻、王肅之流，穿鑿傅會，千岐萬轍，使學者無所依據，然後王弼一舉而廢之。夫易，象也，廢虞、鄭之言可矣，而可以廢聖人之言乎？且其言曰：「蹄者所以取兔，得兔而忘蹄；筌者所以取魚，得魚而忘筌。」然則舍筌蹄而求魚兔，弼亦知其不可矣。自仲尼沒千有餘年，斯文幸而未喪，然聖人之意湮沒不明，其去亡蓋無幾。近世易家頗悟王弼之失，恨其燭理不明，顧乃採拾魏、晉諸儒之談，王弼已棄之糟粕，更取而陳之，其為後學詆訶，無足怪者。然孟子有言：「理義者，人心之所同然者也。」今之學者，雖狥王弼之陋，至於互體，時有所合，未嘗不致疑焉。然其心以為聖人之所未嘗言，而互體之說無一定之據，不若王氏之簡且便也。嗚呼！此豈學者之罪哉！今故取仲尼四象八卦之文，略陳梗槩，覽者得以考焉。或問曰：「四象八卦，如子之言，則聖人曷不明以告人乎？」應之曰：「昔者伏羲氏始畫八卦也，未嘗有六畫也，而文王重之。夫六畫者，非文王之所造也，自伏羲而有之矣。文王之為六十四也，未嘗有兌下乾上也，而夫子陳之。夫兌下乾上者，非夫子之所造也，自文王而有之矣。文王之言曰履虎尾，不咥人，亨者，由履之成卦而言之也。夫子之言曰：說而應乎乾上天下澤，履者，由兌下乾上而言之也。今之所謂四象八卦者，夫子既言之矣，小子述焉。如使聖人一一而告之，則伏羲以來有不勝言者矣。」或者又曰：「聖人之經不可使易知，其言曲而中，其事肆而隱，舉一隅不以三隅反，則不復也。今子發聖人之奧而舉其四隅，毋乃非聖人之意歟？」應之曰：「然，吾罪也夫，吾罪也夫！雖然，吾有不得已也。自仲尼沒千有餘年，未有能以一隅反者，幸而得之，又將隱而藏之，吾懼失聖人之意也，敢求明哲，以正斯言。」紹興甲戌秋九月，崇仁學易堂書。周易經傳集解卷五。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
